{
  "aggregate_id": "DEF-NRS-484A-125::moped",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes human-powered devices, which are expressly excluded from the vehicle category required by the moped definition."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "Neither the bus contract nor the admitting words impose a two-wheel minimum, so an admitted member need not satisfy the covering class's two-or-three-wheel requirement."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a person, whereas the moped definition admits a kind of vehicle device."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Commercial mass or licensing does not establish two or three wheels, while the admitting words permit fewer wheels than the covering contract requires."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The contract's bicycle with an assisting motor retains human-powered propulsion, which the vehicle definition excludes independently of the express statutory electric-bicycle exclusion."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "underdetermined",
      "reason": "The defined electric-scooter exception requires the 100-pound and 20-mph limits, but the class contract requires neither and therefore can describe scooters outside that exception that the moped language admits."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Emergency designation supplies no two-or-three-wheel restriction, so it does not establish that every admitted member satisfies the quoted ru.moped contract."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting vehicle contract supplies no wheel-count restriction that closes the gap between the definition's maximum of three wheels and the covering contract's requirement of two or three."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The express moped definition admits the jurisdiction-classified, low-power two- or three-wheelers described by this contract."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Excluding separately classified powered two-wheelers does not exclude one-wheelers, which the admitting words can reach but the ru.moped contract does not cover."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "Every admitted member has two or three wheels under its own contract and satisfies the jurisdiction's moped definition, establishing membership in the proposed covering class."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official service and identifying equipment do not require two or three wheels, so the covering contract does not account for every member the admitting words can reach."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes persons rather than the vehicle devices admitted by the moped definition, including when those persons use wheelchairs or assistive devices."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "A pedestrian carrying a cane or receiving guidance remains a person rather than a vehicle device admitted by the definition."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract's on-track equipment need not be used exclusively upon stationary rails, so the quoted exception does not exclude every member the admitting words could reach."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School-bus designation and markings impose no two-or-three-wheel requirement, leaving the proposed coverage incomplete for members admitted with fewer wheels."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "The passenger-for-hire contract imposes no wheel count, whereas the proposed covering class requires two or three wheels and the admitting definition does not."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Neither branch of this contract establishes the two-or-three-wheel requirement needed to place every admitted member in ru.moped."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The drawn-vehicle or combination contract supplies no two-wheel minimum, so it does not establish complete coverage by the narrower ru.moped contract."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public-transit service and identifying displays do not establish two or three wheels, leaving admitted members outside the demonstrated scope of the covering contract."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body does not establish two or three wheels, so the definition's maximum wheel count cannot prove coverage by ru.moped."
    }
  ]
}

